#include <bits/stdc++.h>
using namespace std;

const __int128 MOD = 998244353;

__int128 mod_pow(__int128 base, __int128 exp, __int128 mod) {
    __int128 result = 1;
    __int128 b = base % mod;
    while (exp > 0) {
        if (exp & 1) result = (result * b) % mod;
        b = (b * b) % mod;
        exp >>= 1;
    }
    return result;
}

__int128 mod_inverse(__int128 a, __int128 m) {
    // Fermat's little theorem since m is prime
    return mod_pow(a, m - 2, m);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int testCount = 1;
    // To match the Java code, the number of test cases is fixed at 1
    while (testCount--) {
        long long n, m;
        cin >> n >> m;
        long long l, r;
        cin >> l >> r;
        long long diff = r - l;
        long long evenPart = diff / 2 + 1;
        long long oddPart = (diff + 1) / 2;

        __int128 total_cells = (__int128)n * m;
        __int128 diff_plus_one = (__int128)diff + 1;

        if ((n * m) % 2 == 1) {
            __int128 base = diff_plus_one;
            __int128 res = mod_pow(base, total_cells, MOD);
            cout << (long long)res << "\n";
        } else {
            __int128 sum_parts = (__int128)(evenPart + oddPart);
            __int128 diff_parts = (__int128)(evenPart - oddPart);
            __int128 p1 = mod_pow(sum_parts, total_cells, MOD);
            __int128 p2 = mod_pow(diff_parts, total_cells, MOD);
            __int128 total = (p1 + p2) % MOD;
            __int128 inv_two = mod_inverse(2, MOD);
            __int128 answer = (total * inv_two) % MOD;
            cout << (long long)answer << "\n";
        }
    }
    return 0;
}

